package org.mockito;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.hamcrest.Matcher;
import org.hamcrest.core.IsNull;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.matchers.*;
import org.mockito.internal.matchers.apachecommons.ReflectionEquals;
import org.mockito.internal.progress.HandyReturnValues;
import org.mockito.internal.progress.MockingProgress;
import org.mockito.internal.progress.ThreadSafeMockingProgress;
import static org.junit.Assert.*;
import static org.mockito.Matchers.anyObject;

/**
 * Unit tests for org.mockito.Matchers.anyObject()
 */
public class Matchers_anyObject_TriageGen0Test {

    @Test
    public void testAnyObjectReturnsNull() {
        // The implementation of anyObject() calls reportMatcher(Any.ANY).returnNull()
        // Therefore, it should return null regardless of the generic type T.

        String resultString = anyObject();
        Integer resultInteger = anyObject();
        Object resultObject = anyObject();
        Double resultDouble = anyObject();

        assertNull("anyObject() should return null for String type", resultString);
        assertNull("anyObject() should return null for Integer type", resultInteger);
        assertNull("anyObject() should return null for Object type", resultObject);
        assertNull("anyObject() should return null for Double type", resultDouble);
    }

    @Test
    @SuppressWarnings("unchecked")
    public void testAnyObjectWithComplexType() {
        // Testing with a custom class to ensure generic casting works as expected
        class TestClass {}
        TestClass result = anyObject();
        assertNull("anyObject() should return null for custom class type", result);
    }
}
